import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shippingFee } from '../src/shipping.js';

test('a large order ships free', () => {
  assert.equal(shippingFee(8000, 'near'), 0);
});

test('a small order pays the fee of its region', () => {
  assert.equal(shippingFee(1200, 'near'), 600);
  assert.equal(shippingFee(1200, 'far'), 900);
  assert.equal(shippingFee(1200, 'island'), 1500);
});

test('an unknown region is an error', () => {
  assert.throws(() => shippingFee(1200, 'moon'), /unknown region/);
});

test('an order of exactly 5,000 yen ships free in every region', () => {
  assert.equal(shippingFee(5000, 'near'), 0);
  assert.equal(shippingFee(5000, 'far'), 0);
  assert.equal(shippingFee(5000, 'island'), 0);
});

test('an order of 4,999 yen still pays the fee of its region', () => {
  assert.equal(shippingFee(4999, 'near'), 600);
  assert.equal(shippingFee(4999, 'far'), 900);
  assert.equal(shippingFee(4999, 'island'), 1500);
});

test('an order just over 5,000 yen still ships free', () => {
  assert.equal(shippingFee(5001, 'near'), 0);
});

test('an unknown region is still an error at exactly 5,000 yen', () => {
  assert.throws(() => shippingFee(5000, 'moon'), /unknown region/);
});
